/// Apply `function` to each element of `input`, producing a new `Vec`
/// containing the results.
///
/// This is intentionally implemented without the standard library's
/// `map`/`collect` combinators.
pub fn map<T, U, F>(input: Vec<T>, mut function: F) -> Vec<U>
where
    F: FnMut(T) -> U,
{
    let mut output = Vec::with_capacity(input.len());

    for value in input {
        output.push(function(value));
    }

    output
}
EOF
